import{_ as h,o as i,c as t,j as a,a as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"몬스터 배치 M001","description":"","frontmatter":{},"headers":[],"relativePath":"world/Monster-Batch-M001.md","filePath":"world/Monster-Batch-M001.md"}'),o={name:"world/Monster-Batch-M001.md"};function n(d,l,u,s,c,b){return i(),t("div",null,[...l[0]||(l[0]=[a("h1",{id:"몬스터-배치-m001",tabindex:"-1"},[r("몬스터 배치 M001 "),a("a",{class:"header-anchor",href:"#몬스터-배치-m001","aria-label":'Permalink to "몬스터 배치 M001"'},"​")],-1),a("p",null,"이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.",-1),a("ul",null,[a("li",null,[r("원본 앵커: "),a("code",null,"docs/game-logic/World-Narrative-Atlas.md")]),a("li",null,[r("원본 해시: "),a("code",null,"61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1")])],-1),a("h2",{id:"g01e01-·-범람멧돼지-대왕-철갑",tabindex:"-1"},[r("G01E01 · 범람멧돼지 대왕 '철갑' "),a("a",{class:"header-anchor",href:"#g01e01-·-범람멧돼지-대왕-철갑","aria-label":`Permalink to "G01E01 · 범람멧돼지 대왕 '철갑'"`},"​")],-1),a("ul",null,[a("li",null,"그룹: G01"),a("li",null,"역할군: 통제자"),a("li",{"scenarios:[G01-SC1,G01-SC2]":""},"연결:")],-1),e('<h3 id="역할·신체" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>범람멧돼지군의 알파 컨트롤러가 한강 하류 폐기물 더미 위에 군림한다. 4미터에 달하는 거구가 금속 잔해를 등에 두르고 다니면서 주변 하수관을 뒤흔든다.</p><h3 id="기원" tabindex="-1">기원 <a class="header-anchor" href="#기원" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>G01-SC1 대홍수가 휩쓴 오염 습지에서 태어난 변이종이 초기 무리를 장악했다. 이후 군락 전체의 번식과 영토 확장을 주도하면서 한강 남부 생태계를 재편했다.</p><h3 id="서식" tabindex="-1">서식 <a class="header-anchor" href="#서식" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>도성 남부 범람 구역과 연결된 하수 터널 깊숙이 자리를 잡았다. 물이 차오르는 장마철에만 지표로 올라와 주변을 정찰한다.</p><h3 id="필요·경제" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>부패한 유기물과 녹슨 금속 이온을 주 에너지원으로 삼는다. 무리 전체가 수집한 자원을 독점적으로 소비하면서 군락의 생존을 유지한다. G01-SC2에서 에너지 고갈 시 전체 군락이 장기 동면에 들어가는 사실이 확인됐다.</p><h3 id="생애·정비" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>평생 단 한 번의 번식기를 거친 뒤 등에 붙은 철갑을 지속적으로 갱신한다. 부하들이 가져온 금속 조각을 자신의 체액으로 용접하듯 붙여서 방어력을 높인다.</p><h3 id="행동·위계" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>낮은 주파수 울음으로 절대 명령을 내린다. 모든 멧돼지가 즉시 복종하면서 E02부터 E04까지가 그 신호를 해석해 하위 개체에게 전달한다. 이 구조가 군락의 계층을 안정적으로 유지한다.</p><h3 id="단계적-위협" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>먼저 영역 경고 울음을 터뜨려 침입자를 위협한다. 이어서 육중한 몸으로 돌진하면서 등에 붙은 금속 파편을 사방으로 살포한다. 마지막으로 군락 전체를 소집해 압도적인 수로 포위한다.</p><h3 id="전투·대응" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 고주파 음향 발생기를 설치하면 철갑의 공진을 유발해 균열을 만든다. 실패하면 대왕의 돌진이 하수벽을 무너뜨려 주변 구역을 침수시키고 시민 대피 비용이 급증한다. 성공 신호는 철갑 표면에 나타나는 균열음이다.</p><h3 id="협상·도덕-선택" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>군락의 생태 균형을 유지하는 존재이다. 과도한 사냥은 하수 시스템 전체를 마비시켜 서울 남부 주민의 식수 오염을 초래한다. G01-SC3에서 제한적 협상이 가능하지만 거부 시 군락이 적극적으로 인간 거주지를 침범한다.</p><h3 id="시나리오-연결" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC1, G01-SC2, G01-SC3에서 핵심 역할을 한다.</p><h2 id="g01e02-·-범람멧돼지-정찰꾼-흙코" tabindex="-1">G01E02 · 범람멧돼지 정찰꾼 &#39;흙코&#39; <a class="header-anchor" href="#g01e02-·-범람멧돼지-정찰꾼-흙코" aria-label="Permalink to &quot;G01E02 · 범람멧돼지 정찰꾼 &#39;흙코&#39;&quot;">​</a></h2>',21),a("ul",null,[a("li",null,"그룹: G01"),a("li",null,"역할군: 일반 생태형"),a("li",{"scenarios:[G01-SC1]":""},"연결:")],-1),e('<h3 id="역할·신체-1" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-1" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>긴 코가 습지 진흙 속에 파묻힌 채 주변 냄새를 읽는다. 얇고 유연한 다리가 물살을 헤치며 빠르게 이동한다.</p><h3 id="기원-1" tabindex="-1">기원 <a class="header-anchor" href="#기원-1" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>G01-SC1 홍수 생존자 혈통이 대왕의 첫 번째 새끼 무리에서 자라났다. 이후 군락의 외곽 경계를 담당하는 정찰 네트워크를 형성했다.</p><h3 id="서식-1" tabindex="-1">서식 <a class="header-anchor" href="#서식-1" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>범람 구역 외곽의 얕은 물웅덩이와 지하 배수로를 오간다. 낮에는 진흙 속에 몸을 숨기고 밤에만 활동한다.</p><h3 id="필요·경제-1" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-1" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>부패한 수초와 작은 물고기를 포획해 영양을 섭취한다. 가장 신선한 부위를 대왕에게 바치면서 군락의 정보와 자원을 동시에 순환시킨다.</p><h3 id="생애·정비-1" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-1" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>2년마다 털을 갈면서 부서진 코끝을 진흙과 타액으로 덮어 새로운 감각 수용체를 만든다. 이 과정에서 주변 지형 정보를 업데이트한다.</p><h3 id="행동·위계-1" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-1" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 낮은 울음이 전달되기 전에 먼저 위험 냄새를 감지한다. 특유의 코 울음으로 E03과 E04에게 신호를 보내 무리 전체를 경계 태세로 만든다.</p><h3 id="단계적-위협-1" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-1" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>먼저 낮은 코 울음으로 위치를 알린다. 이어서 주변 개체를 불러 모아 집단으로 포위한다. 마지막으로 대왕을 유인해 결정타를 가한다.</p><h3 id="전투·대응-1" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-1" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 진흙 속에 설치한 함정에 유인하면 코가 함정에 걸려 움직임이 둔해진다. 실패하면 정찰꾼이 무리를 불러들여 하수관을 막아 시민 이동 경로를 차단한다. 성공 신호는 코에서 흘러나오는 진흙 거품이다.</p><h3 id="협상·도덕-선택-1" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-1" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>신선한 유기 폐기물을 특정 지점에 놓아두면 일시적으로 경계선을 뒤로 물린다. 그러나 군락 전체가 식량 부족에 처하면 정찰 범위를 인간 거주지까지 확장해 식수원을 오염시킨다.</p><h3 id="시나리오-연결-1" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-1" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC1에서 정찰 역할을 한다.</p><h2 id="g01e03-·-범람멧돼지-청소부-녹철이" tabindex="-1">G01E03 · 범람멧돼지 청소부 &#39;녹철이&#39; <a class="header-anchor" href="#g01e03-·-범람멧돼지-청소부-녹철이" aria-label="Permalink to &quot;G01E03 · 범람멧돼지 청소부 &#39;녹철이&#39;&quot;">​</a></h2><ul><li>그룹: G01</li><li>역할군: 일반 생태형</li><li>연결: {}</li></ul><h3 id="역할·신체-2" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-2" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>강한 턱이 녹슨 금속 파이프를 부수고 산성 침이 부식물을 녹인다. 몸통에 붙은 녹 조각이 주변 환경과 동화된다.</p><h3 id="기원-2" tabindex="-1">기원 <a class="header-anchor" href="#기원-2" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>하수 처리장 폐기물 더미에서 자란 개체가 군락의 자원 순환을 담당하게 되었다. G01-SC2에서 이 개체들이 군락의 폐기물 처리 효율을 높인 기록이 남았다.</p><h3 id="서식-2" tabindex="-1">서식 <a class="header-anchor" href="#서식-2" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>금속 폐기물이 쌓인 하수 터널 바닥을 주로 돌아다닌다. 산성 물이 고인 웅덩이 주변에서 가장 활발하다.</p><h3 id="필요·경제-2" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-2" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>녹슨 금속과 부식된 유기물을 주식으로 삼는다. 이를 분해하면서 군락 전체에 재활용 가능한 이온을 공급한다. 부족 시 군락 청소 활동이 중단된다.</p><h3 id="생애·정비-2" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-2" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>산성 환경에서 살아남기 위해 피부 표면을 주기적으로 갱신한다. 턱 주변에 쌓인 녹을 씻어내고 새로운 산성 분비선을 만든다.</p><h3 id="행동·위계-2" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-2" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 명령이 없어도 자율적으로 폐기물을 청소한다. 그러나 울음 신호가 들리면 즉시 청소 활동을 중단하고 전투 대형으로 이동한다.</p><h3 id="단계적-위협-2" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-2" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>산성 침을 뿜어 적의 장비를 부식시킨다. 이어서 주변 개체와 함께 포위망을 좁혀 움직임을 봉쇄한다.</p><h3 id="전투·대응-2" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-2" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 중화제를 뿌리면 산성 침이 중화되어 청소부의 공격력이 급감한다. 실패하면 산성액이 플레이어 장비를 녹여 이동 속도를 70% 저하시킨다. 성공 신호는 중화제와 침이 반응하며 피어오르는 하얀 연기이다.</p><h3 id="협상·도덕-선택-2" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-2" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>대량의 금속 폐기물을 특정 터널에 버려두면 청소 활동을 집중시켜 주변 구역을 한동안 비워준다. 그러나 폐기물을 과다 공급하면 군락 규모가 급증해 하수관 막힘 사고가 빈발한다.</p><h3 id="시나리오-연결-2" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-2" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC2에서 자원 순환 증언을 남긴다.</p><h2 id="g01e04-·-범람멧돼지-경비병-강철엄니" tabindex="-1">G01E04 · 범람멧돼지 경비병 &#39;강철엄니&#39; <a class="header-anchor" href="#g01e04-·-범람멧돼지-경비병-강철엄니" aria-label="Permalink to &quot;G01E04 · 범람멧돼지 경비병 &#39;강철엄니&#39;&quot;">​</a></h2>',43),a("ul",null,[a("li",null,"그룹: G01"),a("li",null,"역할군: 일반 생태형"),a("li",{"scenarios:[G01-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-3" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-3" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>두꺼운 가죽 위로 돋아난 거대한 엄니가 금속 파이프를 꿰뚫는다. 몸집이 크고 무거워 물살을 거슬러 올라가는 데 특화됐다.</p><h3 id="기원-3" tabindex="-1">기원 <a class="header-anchor" href="#기원-3" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>대왕 근처에서 자란 호위 혈통이 군락의 핵심 방어선을 형성했다. G01-SC3 기록에서 이 혈통이 대왕의 안전을 최우선으로 지킨 사실이 확인됐다.</p><h3 id="서식-3" tabindex="-1">서식 <a class="header-anchor" href="#서식-3" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>범람 구역 중심부의 좁은 통로와 철문 근처를 순찰한다. 물이 빠진 후에도 진흙이 깊게 고인 곳을 선호한다.</p><h3 id="필요·경제-3" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-3" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>대왕의 보호 임무를 수행하는 대가로 가장 영양가 높은 부패물을 우선 배분받는다. 이 영양 공급이 엄니의 강도를 유지한다.</p><h3 id="생애·정비-3" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-3" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>전투로 부서진 엄니를 정기적으로 갈고 다듬는다. 주변 개체가 가져온 금속 조각으로 깨진 부분을 메운다.</p><h3 id="행동·위계-3" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-3" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 위치를 항상 최우선으로 감시한다. 다른 개체가 10미터 이내로 접근하면 낮은 경고음을 내서 접근을 차단한다.</p><h3 id="단계적-위협-3" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-3" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>강력한 돌진으로 침입자를 밀어내고 이어서 엄니로 찌른다. 위협이 지속되면 주변 경비병을 불러 합동 공격을 펼친다.</p><h3 id="전투·대응-3" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-3" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 함정을 파서 돌진 경로를 유도하면 엄니가 함정 바닥에 박혀 움직임이 30초간 봉쇄된다. 실패하면 경비병이 하수벽을 무너뜨려 주변 지하철역을 침수시킨다. 성공 신호는 엄니가 함정 철근에 걸리는 금속 충돌음이다.</p><h3 id="협상·도덕-선택-3" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-3" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>대왕의 안전을 보장하는 조건으로 특정 통로를 일시 개방한다. 그러나 협상을 어기면 군락 전체가 해당 통로를 요새화해 시민 대피 경로를 영구 차단한다.</p><h3 id="시나리오-연결-3" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-3" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC3에서 호위 역할을 한다.</p><h2 id="g01e05-·-범람멧돼지-독분비자-썩은입" tabindex="-1">G01E05 · 범람멧돼지 독분비자 &#39;썩은입&#39; <a class="header-anchor" href="#g01e05-·-범람멧돼지-독분비자-썩은입" aria-label="Permalink to &quot;G01E05 · 범람멧돼지 독분비자 &#39;썩은입&#39;&quot;">​</a></h2><ul><li>그룹: G01</li><li>역할군: 직능 특수형</li><li>연결: {}</li></ul><h3 id="역할·신체-4" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-4" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>입 주변에 발달한 분비선이 진한 녹색 독액을 뿜어낸다. 몸통에 번진 독 자국이 주변 금속을 서서히 부식시킨다.</p><h3 id="기원-4" tabindex="-1">기원 <a class="header-anchor" href="#기원-4" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>오염된 화학 폐기물 웅덩이에서 생존한 개체가 군락의 특수 공격 수단이 되었다. G01-SC2에서 이 개체들이 적의 장비를 무력화한 사례가 다수 기록됐다.</p><h3 id="서식-4" tabindex="-1">서식 <a class="header-anchor" href="#서식-4" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>독성 화학 물질이 고인 하수 구역 깊숙이 머무른다. 다른 개체들은 독 냄새를 피해 이 구역을 우회한다.</p><h3 id="필요·경제-4" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-4" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>고농도 독성 물질을 섭취하면서 분비선을 강화한다. 군락은 이 개체를 통해 적대 생태와의 경계선을 유지한다.</p><h3 id="생애·정비-4" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-4" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>독 분비 후 입 주변 조직이 손상되면 주변 진흙을 먹어 새로운 분비선을 재생한다. 이 과정에서 독성 내성을 높인다.</p><h3 id="행동·위계-4" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-4" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 울음 신호를 받으면 즉시 독액을 준비한다. 주변 개체와 협력해 적을 포위한 뒤 독을 집중 살포한다.</p><h3 id="단계적-위협-4" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-4" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>먼저 독액을 살포해 적의 움직임을 마비시킨다. 이어서 군락 전체가 마비된 목표를 포위해 마무리한다.</p><h3 id="전투·대응-4" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-4" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 방독면과 중화 스프레이를 동시에 사용하면 독액 효과를 80% 차단한다. 실패하면 독이 장비를 부식시켜 5분 내 이동 불능 상태에 빠진다. 성공 신호는 독액이 중화되며 피어오르는 녹색 연기이다.</p><h3 id="협상·도덕-선택-4" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-4" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>독성 폐기물을 지정된 구역에 버려주면 그 구역을 한동안 비워준다. 그러나 폐기물 양이 과다하면 독분비자 개체 수가 증가해 주변 식수원이 영구 오염된다.</p><h3 id="시나리오-연결-4" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-4" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC2에서 독성 증언을 남긴다.</p><h2 id="g01e06-·-범람멧돼지-진흙건축가-벽돌코" tabindex="-1">G01E06 · 범람멧돼지 진흙건축가 &#39;벽돌코&#39; <a class="header-anchor" href="#g01e06-·-범람멧돼지-진흙건축가-벽돌코" aria-label="Permalink to &quot;G01E06 · 범람멧돼지 진흙건축가 &#39;벽돌코&#39;&quot;">​</a></h2>',43),a("ul",null,[a("li",null,"그룹: G01"),a("li",null,"역할군: 직능 특수형"),a("li",{"scenarios:[G01-SC1]":""},"연결:")],-1),e('<h3 id="역할·신체-5" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-5" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>코와 앞발이 진흙과 금속을 섞어 단단한 구조물을 만든다. 등에 붙은 진흙 덩어리가 주변 환경과 완전히 동화된다.</p><h3 id="기원-5" tabindex="-1">기원 <a class="header-anchor" href="#기원-5" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>습지 건축 본능이 극도로 발달한 변이체가 군락의 둥지망을 설계했다. G01-SC1 기록에서 이 개체가 범람 후 군락 생존율을 높인 사실이 확인됐다.</p><h3 id="서식-5" tabindex="-1">서식 <a class="header-anchor" href="#서식-5" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>범람 후 남은 진흙 지대와 무너진 콘크리트 잔해 사이를 오간다. 이곳에서 새로운 통로와 둥지를 지속적으로 건설한다.</p><h3 id="필요·경제-5" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-5" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>진흙과 부서진 금속 잔해를 주요 자원으로 사용한다. 건축 활동을 통해 군락 전체의 은폐와 이동 경로를 확보한다.</p><h3 id="생애·정비-5" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-5" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>건축한 구조물이 무너지면 즉시 주변 진흙을 모아 보수한다. 이 과정에서 새로운 통로를 추가하면서 군락 영역을 확대한다.</p><h3 id="행동·위계-5" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-5" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 거처를 최우선으로 설계한다. 다른 개체들이 가져온 자재를 받아 즉시 벽과 통로를 보강한다.</p><h3 id="단계적-위협-5" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-5" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>진흙 함정을 설치해 침입자를 가두고 이어서 천장을 붕괴시켜 매몰시킨다. 위협 수준이 높아지면 주변 통로를 모두 폐쇄한다.</p><h3 id="전투·대응-5" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-5" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 지반 강화제를 뿌리면 진흙 구조물이 경화되어 함정 효과를 상실한다. 실패하면 붕괴로 인해 플레이어가 3턴 동안 이동 불능에 빠지고 시민 구조 비용이 2배 증가한다. 성공 신호는 경화된 진흙이 딱딱한 소리를 내며 갈라지는 것이다.</p><h3 id="협상·도덕-선택-5" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-5" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>인간 건축 기술을 보여주면 호기심을 보이며 특정 통로를 개방한다. 그러나 기술을 공유하지 않으면 군락이 인간 지하 시설을 적극적으로 점령해 지하철 운행을 마비시킨다.</p><h3 id="시나리오-연결-5" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-5" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC1에서 둥지 관련 증언을 남긴다.</p><h2 id="g01e07-·-범람멧돼지-무리인도자-울음왕" tabindex="-1">G01E07 · 범람멧돼지 무리인도자 &#39;울음왕&#39; <a class="header-anchor" href="#g01e07-·-범람멧돼지-무리인도자-울음왕" aria-label="Permalink to &quot;G01E07 · 범람멧돼지 무리인도자 &#39;울음왕&#39;&quot;">​</a></h2><ul><li>그룹: G01</li><li>역할군: 직능 특수형</li><li>연결: {}</li></ul><h3 id="역할·신체-6" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-6" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>목 주변에 발달한 공명 기관이 저주파 울음을 크게 증폭한다. 몸통이 울음에 따라 진동하면서 주변 물살을 흔든다.</p><h3 id="기원-6" tabindex="-1">기원 <a class="header-anchor" href="#기원-6" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>대왕의 직계 혈통 중에서 울음 전달 능력이 특화된 개체가 군락의 중계 임무를 맡았다. G01-SC3에서 이 개체가 군락 전체의 통합을 유지한 기록이 남았다.</p><h3 id="서식-6" tabindex="-1">서식 <a class="header-anchor" href="#서식-6" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>군락 중심부의 넓은 공동에 머무른다. 울음이 잘 퍼지는 터널 교차로를 선호한다.</p><h3 id="필요·경제-6" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-6" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>울음 발생에 많은 에너지를 소비한다. 주변 개체들이 가져온 영양분을 우선적으로 섭취하면서 공명 기관을 유지한다.</p><h3 id="생애·정비-6" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-6" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>성대와 공명 기관을 정기적으로 점검한다. 손상된 부위를 진흙과 타액으로 메우면서 울음 주파수를 조정한다.</p><h3 id="행동·위계-6" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-6" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 명령을 E02-E04에게 먼저 전달한다. 저주파를 증폭시켜 군락 전체에 동시에 퍼뜨리면서 행동 통일성을 유지한다.</p><h3 id="단계적-위협-6" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-6" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>강력한 울음으로 주변 개체를 한꺼번에 소집한다. 소집된 무리가 합동으로 침입자를 압박한다.</p><h3 id="전투·대응-6" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-6" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 특수 소음 차단 헤드셋을 착용하고 울음 발생 지점을 향해 고주파 교란기를 발사하면 공명 기관이 과부하에 빠진다. 실패하면 군락 전체가 소집되어 플레이어 퇴로를 완전히 차단한다. 성공 신호는 울음왕의 목에서 나는 불협화음이다.</p><h3 id="협상·도덕-선택-6" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-6" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>울음 패턴을 분석해 특정 리듬으로 응답하면 제한적 대화를 시도한다. 그러나 군락의 식량이 부족하면 울음왕이 주도적으로 인간 거주지로 침투해 식량 창고를 약탈한다.</p><h3 id="시나리오-연결-6" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-6" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC3에서 통솔 증언을 남긴다.</p><h2 id="g01e08-·-범람멧돼지-금속융합체-융합갑" tabindex="-1">G01E08 · 범람멧돼지 금속융합체 &#39;융합갑&#39; <a class="header-anchor" href="#g01e08-·-범람멧돼지-금속융합체-융합갑" aria-label="Permalink to &quot;G01E08 · 범람멧돼지 금속융합체 &#39;융합갑&#39;&quot;">​</a></h2><ul><li>그룹: G01</li><li>역할군: 첫 번째 정예</li><li>연결: {}</li></ul><h3 id="역할·신체-7" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-7" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>전신에 금속 조각이 피부와 융합되어 두꺼운 갑옷을 형성한다. 움직일 때마다 금속이 서로 마찰하며 날카로운 소리를 낸다.</p><h3 id="기원-7" tabindex="-1">기원 <a class="header-anchor" href="#기원-7" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>극심한 오염 환경에서 생존한 희귀 변이체가 군락의 최정예 친위대로 자리 잡았다. G01-SC2에서 이 개체가 대왕을 직접 호위한 사례가 다수 확인됐다.</p><h3 id="서식-7" tabindex="-1">서식 <a class="header-anchor" href="#서식-7" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>가장 오염된 하수 심층부의 금속 폐기물 더미 속에 머무른다. 다른 개체들은 금속 마찰음을 피해 이 구역을 피한다.</p><h3 id="필요·경제-7" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-7" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>고농도 금속 이온을 지속적으로 섭취하면서 융합 부위를 유지한다. 군락은 이 개체를 통해 강력한 방어선을 구축한다.</p><h3 id="생애·정비-7" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-7" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>융합된 금속 부위가 느슨해지면 주변 폐기물을 먹어 새로운 금속층을 형성한다. 이 과정에서 몸무게가 점차 증가한다.</p><h3 id="행동·위계-7" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-7" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 직속 친위대로 활동한다. 군락 내에서 가장 강력한 전투력을 발휘하며 다른 개체의 명령을 받지 않는다.</p><h3 id="단계적-위협-7" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-7" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>두꺼운 금속 갑옷으로 모든 공격을 막아내면서 육중한 몸으로 돌진한다. 돌진 후 주변 금속 파편을 몸을 흔들어 살포한다.</p><h3 id="전투·대응-7" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-7" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 고출력 전자기 펄스 발생기를 설치하면 융합 금속이 과열되어 움직임이 40% 저하된다. 실패하면 돌진이 플레이어 위치를 강타해 주변 하수관을 파열시키고 오염수가 분출된다. 성공 신호는 금속 갑옷에서 피어오르는 과열 증기이다.</p><h3 id="협상·도덕-선택-7" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-7" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>융합 과정에서 겪는 지속적인 고통을 인정하고 특정 금속 폐기물을 제공하면 일시적으로 물러선다. 그러나 거부하면 친위대 전체가 인간 시설을 공격해 전력 공급을 차단한다.</p><h3 id="시나리오-연결-7" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-7" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC2에서 엘리트로서의 역할을 수행한다.</p><h2 id="g01e09-·-범람멧돼지-독왕-맹독엄니" tabindex="-1">G01E09 · 범람멧돼지 독왕 &#39;맹독엄니&#39; <a class="header-anchor" href="#g01e09-·-범람멧돼지-독왕-맹독엄니" aria-label="Permalink to &quot;G01E09 · 범람멧돼지 독왕 &#39;맹독엄니&#39;&quot;">​</a></h2><ul><li>그룹: G01</li><li>역할군: 두 번째 정예</li><li>연결: {}</li></ul><h3 id="역할·신체-8" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-8" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>거대한 엄니에 강력한 독이 스며들어 있다. 입 주변의 분비선이 독액을 엄니 표면에 지속적으로 코팅한다.</p><h3 id="기원-8" tabindex="-1">기원 <a class="header-anchor" href="#기원-8" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>독분비자와 금속융합체의 교배 결과로 태어난 최상위 전투체이다. G01-SC3에서 이 개체가 군락의 최종 방어선을 담당한 기록이 남았다.</p><h3 id="서식-8" tabindex="-1">서식 <a class="header-anchor" href="#서식-8" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>독성과 금속이 공존하는 하수 최심부에 독자 영역을 구축했다. 다른 개체들은 독 냄새를 감지하고 접근을 자제한다.</p><h3 id="필요·경제-8" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-8" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>독성 물질과 금속 이온을 동시에 섭취하면서 엄니의 독성을 유지한다. 군락은 이 개체를 통해 최강의 전투력을 확보한다.</p><h3 id="생애·정비-8" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-8" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>독과 금속의 균형이 깨지면 주변 폐기물을 먹어 새로운 균형을 찾는다. 이 과정에서 엄니 표면의 독 코팅이 두꺼워진다.</p><h3 id="행동·위계-8" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-8" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>대왕의 최측근으로 활동한다. 독립적으로 판단해 군락의 최종 방어와 공격을 주도한다.</p><h3 id="단계적-위협-8" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-8" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>독이 스며든 엄니로 적을 찌르고 동시에 독액을 살포한다. 이어서 주변 군락을 불러 합동 공격을 펼친다.</p><h3 id="전투·대응-8" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-8" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 최고급 방호복과 강력한 해독 주사기를 동시에 사용하면 독 효과를 완전히 중화한다. 실패하면 독이 혈관으로 침투해 2턴 내 행동 불능에 빠지고 주변 시민이 집단 중독된다. 성공 신호는 엄니에서 떨어지는 중화된 독액 방울이다.</p><h3 id="협상·도덕-선택-8" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-8" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>극심한 고통을 안고 살아가는 존재이다. 공감대를 형성하고 특정 화학 폐기물을 제공하면 협력한다. 그러나 협상을 거부하면 독왕이 주도하는 군락 총공격으로 서울 남부 전체가 오염 위기에 처한다.</p><h3 id="시나리오-연결-8" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-8" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC3에서 보스급 위협으로 등장한다.</p><h2 id="g01e10-·-범람멧돼지-철갑둥지-강철습지" tabindex="-1">G01E10 · 범람멧돼지 철갑둥지 &#39;강철습지&#39; <a class="header-anchor" href="#g01e10-·-범람멧돼지-철갑둥지-강철습지" aria-label="Permalink to &quot;G01E10 · 범람멧돼지 철갑둥지 &#39;강철습지&#39;&quot;">​</a></h2>',87),a("ul",null,[a("li",null,"그룹: G01"),a("li",null,"역할군: 환경 거점형"),a("li",{"scenarios:[G01-SC1,G01-SC2,G01-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-9" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-9" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>대왕의 거처이자 군락 전체의 중심지이다. 살아있는 금속-진흙 복합 구조물이 주변 하수관을 따라 천천히 확장된다.</p><h3 id="기원-9" tabindex="-1">기원 <a class="header-anchor" href="#기원-9" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>수십 년간 축적된 군락 건축물과 대왕의 체액이 서로 융합되어 살아있는 요새가 되었다. G01-SC1부터 이 구조물이 군락의 생존 기반이 되었다.</p><h3 id="서식-9" tabindex="-1">서식 <a class="header-anchor" href="#서식-9" aria-label="Permalink to &quot;서식&quot;">​</a></h3><p>한강 하류 최대 범람 구역 중심에 자리 잡았다. 주변 진흙과 금속 잔해를 지속적으로 흡수하면서 영역을 넓힌다.</p><h3 id="필요·경제-9" tabindex="-1">필요·경제 <a class="header-anchor" href="#필요·경제-9" aria-label="Permalink to &quot;필요·경제&quot;">​</a></h3><p>군락 전체가 수집한 자원을 공급받는다. 구조물 자체가 금속을 흡수해 성장하면서 군락의 안정된 보금자리를 제공한다.</p><h3 id="생애·정비-9" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-9" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>손상된 부분이 생기면 주변 개체 전체가 복구 작업에 동원된다. 대왕의 체액이 공급되면서 구조물의 재생 속도가 빨라진다.</p><h3 id="행동·위계-9" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-9" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>군락의 심장으로서 모든 개체가 본능적으로 보호한다. 구조물 내부에서 발생하는 진동이 군락 전체의 행동을 조율한다.</p><h3 id="단계적-위협-9" tabindex="-1">단계적 위협 <a class="header-anchor" href="#단계적-위협-9" aria-label="Permalink to &quot;단계적 위협&quot;">​</a></h3><p>요새 자체가 함정을 작동시키고 자가 방어 기관을 발동한다. 위협 수준이 높아지면 군락 전체를 총동원해 침입자를 포위한다.</p><h3 id="전투·대응-9" tabindex="-1">전투·대응 <a class="header-anchor" href="#전투·대응-9" aria-label="Permalink to &quot;전투·대응&quot;">​</a></h3><p>플레이어가 구조물 핵심부에 산성 용매를 주입하면 내부 금속-진흙 결합이 약화되어 요새 기능이 50% 저하된다. 실패하면 요새가 주변 하수관을 모두 폐쇄해 서울 남부 지하 전체를 침수시킨다. 성공 신호는 구조물 표면에서 피어오르는 녹슨 거품이다.</p><h3 id="협상·도덕-선택-9" tabindex="-1">협상·도덕 선택 <a class="header-anchor" href="#협상·도덕-선택-9" aria-label="Permalink to &quot;협상·도덕 선택&quot;">​</a></h3><p>군락의 생태 중심지이다. 파괴 시 서울 남부 하수 시스템 전체가 붕괴한다. G01-SC1~SC3에서 핵심 협상과 도덕적 선택의 지점이 된다. 협상을 거부하면 요새가 군락을 총동원해 인간 거주지를 영구적으로 점령한다.</p><h3 id="시나리오-연결-9" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-9" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G01-SC1, G01-SC2, G01-SC3 전부에서 최종 무대가 된다.</p>',20)])])}const m=h(o,[["render",n]]);export{p as __pageData,m as default};
